(()=>{
 const api=PeninsulaText,host=document.querySelector('#text-settings');let selected='large';
 host.innerHTML='<h2>Настройки текста</h2><div class="text-assignments">'+Object.entries(api.roles).map(([id,label])=>'<label>'+label+'<select data-role="'+id+'">'+Object.entries(api.names).map(([value,name])=>'<option value="'+value+'">'+name+'</option>').join('')+'</select></label>').join('')+'</div><div class="text-tabs" role="tablist" aria-label="Пресеты текста">'+Object.entries(api.names).map(([id,label])=>'<button type="button" role="tab" id="tab-'+id+'" aria-controls="preset-controls" data-preset="'+id+'">'+label+'</button>').join('')+'</div><div id="preset-controls" role="tabpanel"><label>Выравнивание<select data-field="align"><option value="left">Слева</option><option value="center">По центру</option></select></label><label>Размер шрифта, px<input data-field="size" type="number" min="5" max="32" step="1"></label><label>Отступ от края, px<input data-field="padding" type="number" min="0" max="40" step="1"></label><label>Вверх / вниз, px<input data-field="offset" type="number" min="-60" max="60" step="1"></label><p class="settings-note">Минус — вверх, плюс — вниз. Размеры в пикселях игры 320 × 240.</p><label class="caps-label"><input data-field="uppercase" type="checkbox">Капслок</label><label>Цвет текста<input data-field="color" type="color"></label></div>';
 function sync(){host.querySelectorAll('[data-role]').forEach(e=>e.value=api.state.assignments[e.dataset.role]);host.querySelectorAll('[data-preset]').forEach(e=>{const active=e.dataset.preset===selected;e.setAttribute('aria-selected',String(active));e.tabIndex=active?0:-1});host.querySelector('[role="tabpanel"]').setAttribute('aria-labelledby','tab-'+selected);host.querySelectorAll('[data-field]').forEach(e=>{const v=api.state.presets[selected][e.dataset.field];if(e.type==='checkbox')e.checked=v;else e.value=v})}
 host.addEventListener('click',e=>{const tab=e.target.closest('[data-preset]');if(tab){selected=tab.dataset.preset;sync()}});
 host.querySelector('[role="tablist"]').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();e.stopPropagation();const ids=Object.keys(api.names);selected=ids[e.key==='Home'?0:e.key==='End'?3:(ids.indexOf(selected)+(e.key==='ArrowLeft'?3:1))%4];sync();host.querySelector('[data-preset="'+selected+'"]').focus()});
 host.addEventListener('input',e=>{const role=e.target.dataset.role,field=e.target.dataset.field;if(!role&&!field)return;const state=JSON.parse(JSON.stringify(api.state));if(role)state.assignments[role]=e.target.value;if(field)state.presets[selected][field]=e.target.type==='checkbox'?e.target.checked:e.target.type==='number'?Number(e.target.value):e.target.value;api.update(state)});
 window.addEventListener('text-presets-change',()=>{if(typeof levelFrame!=='undefined'&&!levelFrame.hidden)levelFrame.contentWindow.postMessage({type:'text-presets',settings:api.state},location.origin);if(typeof render==='function')render()});sync();
})();
